/** Owner 10-07 (ball out of bounds): a fractional square's ground anchor, interpolated between whole squares so an
 *  off-pitch point in the stands projects exactly like the squares around it in every orientation. */
export function fractionalSquareAnchor(x: number, y: number): { x: number; y: number } {
  const x0 = Math.floor(x), y0 = Math.floor(y);
  const fx = x - x0, fy = y - y0;
  const a = squareAnchor(x0, y0), b = squareAnchor(x0 + 1, y0);
  const c = squareAnchor(x0, y0 + 1), d = squareAnchor(x0 + 1, y0 + 1);
  const top = { x: a.x + (b.x - a.x) * fx, y: a.y + (b.y - a.y) * fx };
  const bottom = { x: c.x + (d.x - c.x) * fx, y: c.y + (d.y - c.y) * fx };
  return { x: top.x + (bottom.x - top.x) * fy, y: top.y + (bottom.y - top.y) * fy };
}

/** Owner 10-07: where the ball-out stamp sits - on the crossed square's edge (the pitch edge the hop from `last` to
 *  `exit` crosses). */
export function stampAnchorSquare(last: readonly [number, number], exit: readonly [number, number]): [number, number] {
  const dx = exit[0] - last[0], dy = exit[1] - last[1];
  const limits: number[] = [];
  if (dx < 0) limits.push((last[0] + 0.5) / -dx);
  if (dx > 0) limits.push((PITCH_COLS - 0.5 - last[0]) / dx);
  if (dy < 0) limits.push((last[1] + 0.5) / -dy);
  if (dy > 0) limits.push((PITCH_ROWS - 0.5 - last[1]) / dy);
  const t = limits.length ? Math.min(1, ...limits) : 1;
  return [last[0] + dx * t, last[1] + dy * t];
}

/** Owner 10-10: the server's PlayerAction.SECURE_THE_BALL wire name (`secureTheBall`), normalised like actionEmoji. */
function isSecureTheBallAction(action: string | null | undefined): boolean {
  return (action ?? '').toLowerCase().replace(/[^a-z]/g, '') === 'securetheball';
}

function isMovingPlayerAction(action: string | null | undefined): boolean {
  return action === 'move' || action === 'blitzMove' || action === 'handOverMove'
    || action === 'passMove' || action === 'foulMove' || action === 'throwTeamMateMove'
    || action === 'kickTeamMateMove' || action === 'gazeMove' || action === 'putridRegurgitationMove'
    || action === 'kickEmBlitz' || action === 'secureTheBall' || action === 'puntMove';
}
/**
 * A server movement is commonly published as two frames: reservation/roll offers first, physical coordinate
 * second. Rebuilding every Pixi token for the first frame adds no visual truth and interrupts the live tween.
 * This predicate is intentionally conservative: it permits a projection-only redraw only while the same moving
 * actor and every physical pitch primitive are unchanged. Any uncertain board mutation falls back to refresh().
 */
/** P0 (09-14): set equality for the pick-setter guards; null ≡ empty. */
export function sameIdSet(a: ReadonlySet<string> | null, b: ReadonlySet<string> | null): boolean {
  const sa = a && a.size > 0 ? a : null;
  const sb = b && b.size > 0 ? b : null;
  if (sa === sb) return true;
  if (!sa || !sb || sa.size !== sb.size) return false;
  for (const id of sa) if (!sb.has(id)) return false;
  return true;
}

/** Owner 10-03: casualty blood splatter art (assets/decorations/blood/blood-N-4x.png). A glob, so the build never
 *  breaks while the art is absent - the decals simply do not draw. */
const BLOOD_DECAL_URLS: string[] = Object.entries(
  import.meta.glob('../assets/decorations/blood/blood-*-4x.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>,
).sort(([a], [b]) => a.localeCompare(b)).map(([, url]) => url);
/** Owner 10-21: the movement-remaining badge art by value 0..12 (128/ = the 4x source of a 32 px badge). A glob, so the
 *  build never breaks while the art is absent - the badge simply does not draw. */
const MOVE_REMAINING_URLS: Map<number, string> = new Map(
  Object.entries(
    import.meta.glob('../assets/decorations/move-remaining/128/move-remaining-*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>,
  )
    .map(([path, url]) => [Number(/move-remaining-(\d+)\.png$/.exec(path)?.[1] ?? Number.NaN), url] as [number, string])
    .filter(([value]) => Number.isInteger(value) && value >= 0 && value <= MOVE_BADGE_MAX),
);
/** Owner 10-21: the activation badge's size in the token's decor-1 units (the chest state markers are 14 too), so it
 *  rides the token's depth and decoration (zoom) scale. */
const MOVE_BADGE_SIZE = 14;
/** The decal covers this share of the tile's on-screen width / height. */
const BLOOD_DECAL_FILL = 0.94;
/** The on-pitch squares that carry a CASUALTY blood spot (FFB BloodSpot.injury = the victim's PlayerState: base 6
 *  Badly Hurt, 7 Serious Injury, 8 RIP; a knock-out's spot, base 5, is not a casualty). */
export function bloodDecalSpots(
  spots: readonly { coordinate?: [number, number] | null; injury?: unknown }[] | null | undefined,
  relocations: readonly BloodSpotRelocation[] = [],
): { x: number; y: number }[] {
  const out: { x: number; y: number }[] = [];
  (spots ?? []).forEach((spot, index) => {
    const base = Number(spot?.injury ?? 0) & 0xff;
    if (base < 6 || base > 8) return;
    if (!isOnPitch(spot?.coordinate ?? null)) return;
    // Owner 10-20: a thrown team-mate's crowd injury bleeds on the square he went out on (BloodSpotRelocation)
    const moved = relocations.find((r) => r.index === index && r.from[0] === spot.coordinate![0] && r.from[1] === spot.coordinate![1] && isCrowdSquare(r.to));
    out.push(moved ? { x: moved.to[0], y: moved.to[1] } : { x: spot.coordinate![0], y: spot.coordinate![1] });
  });
  return out;
}
/** Owner 10-20 ("Blood splatter should go on the outside sideline square"): the server names the LAST IN-BOUNDS square
 *  for the blood spot of a thrown / kicked / swooping team-mate's crowd injury (g1954978 #1443: [9,14]); Modern draws
 *  that ONE spot (bloodspotArray[index], still on `from`) on his crowd square `to` instead. Presentation only. */
export interface BloodSpotRelocation { index: number; from: [number, number]; to: [number, number] }
/** Stable per-square variant + mirror, so a tile's splatter never changes between refreshes. */
export function bloodDecalVariant(x: number, y: number, variants: number): { variant: number; flip: boolean } {
  const hash = Math.abs(Math.imul(x * 73856093 ^ y * 19349663, 2654435761) | 0);
  return { variant: variants > 0 ? hash % variants : 0, flip: ((hash >>> 8) & 1) === 1 };
}

export function movementTokenGenerationSignature(game: GameJson | null): string | null {
  if (!game) return null;
  const acting = game.actingPlayer as { playerId?: unknown; playerAction?: unknown } | null | undefined;
  const action = String(acting?.playerAction ?? '');
  if (!isMovingPlayerAction(action)) return null;
  const field = game.fieldModel;
  return JSON.stringify({
    game: [String(game.gameId), game.turnMode, game.homePlaying, game.half],
    acting: [String(acting?.playerId ?? ''), action],
    defenderId: String((game as { defenderId?: unknown }).defenderId ?? ''),
    throwerId: String((game as { throwerId?: unknown }).throwerId ?? ''),
    passCoordinate: game.passCoordinate ?? null,
    weather: field.weather,
    ball: [field.ballCoordinate, field.ballInPlay, field.ballMoving, field.outOfBounds],
    bomb: [field.bombCoordinate, field.bombMoving],
    players: field.playerDataArray.map((data) => [
      data.playerId, data.playerCoordinate, data.playerState, data.cards ?? [], data.cardEffects ?? [],
    ]),
    bloodspots: field.bloodspotArray ?? [],
    trapDoors: field.trapDoors ?? [],
    chomped: field.chomped ?? {},
    fieldMarkers: field.fieldMarkerArray ?? [],
    playerMarkers: field.playerMarkerArray ?? [],
    diceDecorations: field.diceDecorationArray ?? [],
  });
}


export function canReuseMovementTokenGeneration(previous: GameJson | null, next: GameJson | null): boolean {
  const previousSignature = movementTokenGenerationSignature(previous);
  return previousSignature !== null && previousSignature === movementTokenGenerationSignature(next);
}
