  setRecoveringPlayers(ids: string[]): void {
    const next = new Set(ids);
    if (next.size === this.recoveringPlayers.size && [...next].every((id) => this.recoveringPlayers.has(id))) return;
    this.recoveringPlayers = next;
    this.refresh();
  }
